<script>
  import { pathOf, liveFile } from './windows11-app-helpers.js';
  let { native, execute } = $props();
  const apps = $derived(native.apps);
  const state = $derived(apps.terminal);
  const tab = $derived(state.tabs.find(item => item.id === state.activeTabId));
  const send = (command, target = {}, payload = {}) => execute({ command, target, payload });
  function keys(event) {
    if (event.key === 'Enter' && !event.shiftKey) { event.preventDefault(); send('win11.terminal.run', { tabId: tab.id }); }
    if (event.key === 'ArrowUp' || event.key === 'ArrowDown') { event.preventDefault(); send('win11.terminal.history', { tabId: tab.id }, { direction: event.key === 'ArrowUp' ? 'previous' : 'next' }); }
    if (event.ctrlKey && event.key.toLowerCase() === 'l') { event.preventDefault(); send('win11.terminal.clear', { tabId: tab.id }); }
  }
</script>
<div class="terminal" class:light={state.theme === 'light'} style={`--terminal-font-size:${state.fontSize}px`}>
  <div class="tabs" inert={!!state.ui.dialog}>
    {#each state.tabs as item (item.id)}<div class="tab" class:active={state.activeTabId === item.id}><button class="tab-name" data-control={`terminal-tab-${item.id}`} onclick={() => send('win11.terminal.activate', { tabId: item.id })}><span class="ps-icon">›_</span> Windows PowerShell</button><button class="tab-close" data-control={`terminal-close-${item.id}`} aria-label="Close tab" onclick={() => send('win11.terminal.closeTab', { tabId: item.id })}>×</button></div>{/each}
    <button data-control="terminal-new-tab" aria-label="New tab" onclick={() => send('win11.terminal.new')}>＋</button><button data-control="terminal-profiles" aria-label="Terminal menu" onclick={() => send('win11.apps.menu', { appId: 'terminal' }, { menu: state.ui.menu === 'profiles' ? null : 'profiles' })}>⌄</button>
  </div>
  {#if state.ui.menu && !state.ui.dialog}<div class="w11-app-menu dropdown">
    <button data-control="terminal-menu-new" onclick={() => send('win11.terminal.new')}>Windows PowerShell <span>Local</span></button><hr/>
    <button data-control="terminal-menu-clear" onclick={() => send('win11.terminal.clear', { tabId: tab.id })}>Clear buffer <span>Ctrl+L</span></button>
    <button data-control="terminal-menu-settings" onclick={() => send('win11.terminal.dialog.open', {}, { kind: 'settings' })}>Settings</button>
    <button data-control="terminal-menu-about" onclick={() => send('win11.terminal.dialog.open', {}, { kind: 'about' })}>About</button>
  </div>{/if}
  {#if tab}<div class="terminal-surface" inert={!!state.ui.dialog}>
    <textarea class="output" data-control="terminal-output" data-area="terminal-output" readonly aria-label="Terminal output" value={tab.lines.join('\n')} spellcheck="false" onscroll={event => send('win11.apps.scroll.observe', { appId: 'terminal', area: 'terminal-output' }, { top: event.currentTarget.scrollTop, left: event.currentTarget.scrollLeft })}></textarea>
    <div class="prompt"><label for="terminal-input">PS {pathOf(apps, tab.cwd)}&gt;</label><textarea id="terminal-input" data-control="terminal-input" data-area="terminal-input" aria-label="Virtual command" rows="1" spellcheck="false" value={tab.input} oninput={event => send('win11.terminal.input', { tabId: tab.id }, { input: event.currentTarget.value })} onkeydown={keys} onscroll={event => send('win11.apps.scroll.observe', { appId: 'terminal', area: 'terminal-input' }, { top: event.currentTarget.scrollTop, left: event.currentTarget.scrollLeft })}></textarea><button data-control="terminal-run" aria-label="Run virtual command" disabled={liveFile(apps, tab.cwd)?.kind !== 'folder'} onclick={() => send('win11.terminal.run', { tabId: tab.id })}>↵</button></div>
    {#if liveFile(apps, tab.cwd)?.kind !== 'folder'}<p class="cwd-error">Current folder was deleted. Use ＋ to open a new tab at C:.</p>{/if}
  </div>{/if}
  <div class="status">Local virtual filesystem · Enter to run · ↑↓ history · No host shell</div>
  {#if state.ui.dialog}<div class="dialog-shade" role="dialog" aria-modal="true" aria-label={state.ui.dialog.kind === 'settings' ? 'Terminal settings' : 'About Terminal'}><section class="w11-app-dialog">{#if state.ui.dialog.kind === 'settings'}<h3>Settings</h3><h4>Appearance</h4>
    <label>Application theme<select data-control="terminal-settings-theme" value={state.theme} onchange={event => send('win11.terminal.settings', {}, { theme: event.currentTarget.value, fontSize: state.fontSize })}><option value="dark">Dark</option><option value="light">Light</option></select></label>
    <label>Font size<input class="w11-app-input" data-control="terminal-settings-font" type="range" min="10" max="24" value={state.fontSize} oninput={event => send('win11.terminal.settings', {}, { theme: state.theme, fontSize: Number(event.currentTarget.value) })}/><span>{state.fontSize} pt</span></label>
    <p>Profile: Windows PowerShell appearance. Commands use a deterministic local parser, not PowerShell.</p>
  {:else}<h3>Windows Terminal</h3><p>Period-inspired tabbed terminal for the Windows 11 23H2 scene.</p><p>This offline simulation supports pwd, cd, dir, ls, cat, type, echo, mkdir, touch, copy, move, rename, del, restore, help, and cls.</p><p>No real PowerShell, cmd, WSL, process execution, network, credentials, or host filesystem. Store-delivered Terminal versions vary independently of the Windows build.</p>{/if}
  <div class="dialog-actions"><button class="w11-app-button primary" data-control="terminal-dialog-close" onclick={() => send('win11.terminal.dialog.close')}>Close</button></div></section></div>{/if}
</div>
<style>
  .terminal{--terminal-bg:#0c0c0c;--terminal-fg:#ccc;height:100%;display:flex;flex-direction:column;position:relative;background:var(--terminal-bg);color:var(--terminal-fg);min-width:0;font:13px 'Segoe UI',sans-serif}.terminal.light{--terminal-bg:#fff;--terminal-fg:#222}.tabs{display:flex;gap:3px;align-items:center;background:#252525;padding:5px 8px 0;overflow-x:auto;min-height:36px;color:#ddd}.light .tabs{background:#eee;color:#222}.tabs button{background:transparent;border:0;color:inherit;font:inherit;padding:7px}.tab{display:flex;align-items:center;min-width:190px;border-radius:7px 7px 0 0;background:#303030}.light .tab{background:#ddd}.tab.active{background:var(--terminal-bg);color:var(--terminal-fg)}.tab-name{flex:1;white-space:nowrap;text-align:left}.ps-icon{background:#064779;font:bold 12px Consolas,monospace;padding:1px 3px;color:#fff;margin-right:8px}.terminal-surface{display:flex;flex-direction:column;flex:1;min-height:0;padding:10px 12px 4px}.output{flex:1;min-height:0;resize:none;border:0;outline:none;padding:0;background:var(--terminal-bg);color:var(--terminal-fg);font:var(--terminal-font-size)/1.35 Consolas,'Courier New',monospace;white-space:pre;overflow:auto}.prompt{display:flex;gap:7px;align-items:flex-start;flex:none;font:var(--terminal-font-size)/1.35 Consolas,'Courier New',monospace;padding-top:8px}.prompt label{padding-top:3px;white-space:nowrap;max-width:50%;overflow:hidden;text-overflow:ellipsis}.prompt textarea{flex:1;min-width:0;resize:none;background:var(--terminal-bg);color:var(--terminal-fg);font:inherit;border:0;outline:none;padding:3px;max-height:75px}.prompt button{color:var(--terminal-fg);background:#ffffff15;border:1px solid #ffffff30;border-radius:4px;padding:3px 10px}.light .prompt button{border-color:#ddd;background:#eee}.status{font-size:11px;color:#999;padding:5px 12px;border-top:1px solid #ffffff12}.light .status{border-color:#ddd;color:#666}.cwd-error{color:#f6b2b2;font-size:12px}.dropdown{position:absolute;top:38px;right:12px;z-index:3;width:270px;color:#222}.dropdown button{display:flex;justify-content:space-between;width:100%;padding:8px}.dropdown span{color:#777}.dialog-shade{position:absolute;inset:0;background:#0006;display:grid;place-items:center;z-index:5}.w11-app-dialog{background:#f8f8f8;color:#222;border:1px solid #ccc;border-radius:8px;box-shadow:0 12px 35px #0005;padding:22px;width:min(450px,90%)}.w11-app-dialog h3{margin:0 0 20px;font-size:20px}.w11-app-dialog h4{font-size:15px}.w11-app-dialog label{display:grid;gap:8px;margin:16px 0}.w11-app-dialog select{padding:7px}.w11-app-dialog p{line-height:1.5;color:#666}.dialog-actions{display:flex;justify-content:flex-end;margin-top:18px}.primary{background:#0067c0;color:#fff}@media(max-width:480px){.tab{min-width:165px}.status{font-size:10px}.terminal-surface{padding:8px}.w11-app-dialog{padding:16px}}
</style>
